import json,requests,subprocess,hashlib
from pathlib import Path
p=Path('/tmp/goodsentry-closure-028');f=json.loads((p/'browser-fixture.json').read_text());limited='http://127.0.0.1:18530';original=f['baseURL'];wire=(p/'exporters/json-identity-0.wire').read_bytes();assert len(wire)>1024
q="select encode(payload,'hex') from otlp_log_batches where id=10 and project_id=4";cmd=['docker','exec','gsclosure028-postgres-1','psql','-U','closure028','-d','closure028_limit','-Atc',q];before=bytes.fromhex(subprocess.check_output(cmd,text=True).strip());assert len(before)>1024
s=requests.Session();r=s.post(limited+'/api/v1/login',headers={'Origin':limited},json={'email':f['ownerEmail'],'password':f['ownerPassword']},timeout=15);assert r.status_code==200;log=s.get(limited+f"/api/v1/organizations/{f['orgSlug']}/logs",params={'project':f['projectId'],'query':f['expectedBody']},timeout=15);assert log.status_code==200 and len(log.json()['data'])==1;logid=log.json()['data'][0]['id'];detail=s.get(limited+f"/api/v1/organizations/{f['orgSlug']}/logs/{logid}",timeout=15);assert detail.status_code==413 and 'data' not in detail.json()
r=requests.post(limited+'/v1/logs',headers={'Content-Type':'application/json','X-GoodSentry-Key':f['publicKey']},data=wire,timeout=15);assert r.status_code==413;after=bytes.fromhex(subprocess.check_output(cmd,text=True).strip());assert before==after
s2=requests.Session();login=s2.post(original+'/api/v1/login',headers={'Origin':original},json={'email':f['ownerEmail'],'password':f['ownerPassword']},timeout=15);assert login.status_code==200;full=s2.get(original+f"/api/v1/organizations/{f['orgSlug']}/logs/{logid}",timeout=15);assert full.status_code==200;assert full.json()['data']['logRecord']['body']['stringValue']==f['expectedBody']
report={'passed':True,'limitBytes':1024,'rejectedWireBytes':len(wire),'ingestStatus':r.status_code,'limitedDetailStatus':detail.status_code,'originalDetailStatus':full.status_code,'retainedBatchBytes':len(before),'retainedBatchSHA256':hashlib.sha256(before).hexdigest(),'logId':logid};(p/'limit-report.json').write_text(json.dumps(report,indent=2));print(json.dumps(report))
